import * as React from "react";

export function ShinyTextSheen({ text = "Prismatic", className = "" }: { text?: string; className?: string }): React.JSX.Element {
  const [x, setX] = React.useState(-50);
  React.useEffect(() => { const id = setInterval(() => setX(p => p >= 150 ? -50 : p + 1.5), 16); return () => clearInterval(id); }, []);
  return (
    <div className={`relative inline-block select-none font-display font-black text-5xl ${className}`} style={{ WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent", backgroundClip: "text", background: `linear-gradient(105deg, #888 ${x - 20}%, #fff ${x}%, #e0c87c ${x + 8}%, #fff ${x + 16}%, #888 ${x + 36}%)` }}>
      {text}
    </div>
  );
}

import * as React from "react";
import { ShinyTextSheen } from "./shiny-text-sheen";

export default function ShinyTextSheenDemo(): React.JSX.Element {
  return (
    <div className="flex min-h-[360px] w-full items-center justify-center rounded-2xl bg-neutral-950 p-8 border border-neutral-800">
      <ShinyTextSheen
        text="Next Generation Web Interfaces"
        className="text-3xl sm:text-5xl font-mono font-bold tracking-tight text-white text-center"
      />
    </div>
  );
}
